package com.amora.app;
import android.content.Context;import org.json.*;import java.io.*;import java.net.*;
final class AmoraApi {
 static final String BASE="https://qaiqflcxfxygynumapyp.supabase.co";
 static JSONObject session(Context context)throws Exception{synchronized(SecureStore.class){JSONObject s=new JSONObject(SecureStore.get(context));if(s.getLong("expires")<System.currentTimeMillis()/1000+90){JSONObject next=request("/auth/v1/token?grant_type=refresh_token",new JSONObject().put("refresh_token",s.getString("refresh")),s,false);s.put("access",next.getString("access_token")).put("refresh",next.getString("refresh_token")).put("expires",next.optLong("expires_at",System.currentTimeMillis()/1000+next.optLong("expires_in",3600)));s=new JSONObject(SecureStore.replace(context,s.toString(),s.getString("user")));NativeBridge.event("trackingSessionUpdated",true);}return s;}}
 static JSONObject call(Context context,JSONObject payload)throws Exception{JSONObject s=session(context);return request("/rest/v1/rpc/namora_companion",new JSONObject().put("payload",payload),s,true);}
 static JSONObject request(String path,JSONObject body,JSONObject s,boolean auth)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("apikey",s.getString("key"));if(auth)c.setRequestProperty("Authorization","Bearer "+s.getString("access"));try{try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}int code=c.getResponseCode();if(code>=400)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>2000000)throw new IOException("Response too large");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
}
